def phaseplot(mae,  # CRLD multi-agent environment object
              x:tuple,  # which phase space axes to plot along x axes
              res,  # specify range & resolution
              NrRandom:int=3,  # how many random (in the other dimensions) stratgies for averaging 
              traj_len:int=500,  # trajectory length
              # col:str='LEN',  # color indicates either strength of flow via colormap, otherwise a fixed color name
              cmap='viridis',  # Colormap
              # kind='quiver+samples', # Kind of plot: "streamplot", "quiver+samples", "quiver", ...
              # sf=0.5,  # Scale factor for quiver arrows
              # lw=1.0,  # Line width for streamplot
              # dens=0.75,  # Density for streamplot
              acts=None,  # Action descriptions
              conds=None,  # Conditions descriptions 
              axes:Iterable=None,  # Axes to plot into
              verbose=False,  # shall I talk to you while working?
              ):  
    """
    Create a phase plot in strategy space.
    """
    
    # Fig and Axes
    if axes == None:
        states = mae.Z
        if mae.Z == 1:
            fig, ax = plt.subplots(1, states, figsize=(states * 3.8, 2.8))
            axes = [ax]
        else:
            fig, axes = plt.subplots(1, states, figsize=(states * 3.8, 2.8))
    else:
        axes = axes
        
    # cmap = mpl.cm.get_cmap(cmap)
    ext = np.linspace(0, 1, len(res))
    
    # x axis
    xs = res
    zero = np.zeros((len(xs)))

    # The Plots
    for i in range(len(x[1])): # go through each plot sequentially 
        xinds = (x[0][0], x[1][i], x[2][0])  # fix this later
        # obtain the data to plot
        RPEs, dXs = _data_to_plot(mae, res, xinds, traj_len, NrRandom, 
                             phasespace_items=_strategies, verbose=verbose)
        axes[i].plot(xs, RPEs[i, :], color="blue")
        axes[i].plot(xs, zero, color="grey", ls='dashed')
        twinax = axes[i].twinx()
        twinax.plot(xs, dXs[i, :], color="red")
        
        # Set default limits before aligning 
        axes[i].set_ylim(min(RPEs[i, :]), max(RPEs[i, :]))  # Primary y-axis
        twinax.set_ylim(min(dXs[i, :]), max(dXs[i, :]))     # Secondary y-axis
        if i==len(x[1])-1:
            twinax.set_ylabel("dX", color="red")

        # Align the zero levels of both axes
        align_zero_limits(axes[i], twinax)
        
    # Decorations
    # lens = max(xlens)
    if acts is None:
        acts = [f'act.{i}' for i in range(mae.M)]
        acts = mae.env.Aset
    if conds is None:
        conds = [f'state {i}' for i in range(mae.Z)]
    for i in range(len(x[1])):
        axes[i].set_title(conds[i])
        axes[i].set_xlabel("prob. act. "+str(xinds[2]))
    axes[0].set_ylabel("RPE", color="blue")
    
    # fig.tight_layout()
    
    return axes

