# Function to adjust y-axis limits to ensure 0 is aligned
def align_zero_limits(ax1, ax2, padding_factor=0.05):
    # Get the limits of both y-axes
    ax1_min, ax1_max = ax1.get_ylim()
    ax2_min, ax2_max = ax2.get_ylim()

    # Compute ranges and negative-to-positive ratios
    ax1_range = max(ax1_max, 0) - min(ax1_min, 0)
    ax2_range = max(ax2_max, 0) - min(ax2_min, 0)
    
    ax1_neg_to_pos_ratio = -ax1_min / ax1_max if ax1_max != 0 else 1
    ax2_neg_to_pos_ratio = -ax2_min / ax2_max if ax2_max != 0 else 1
    
    # Adjust limits proportionally to keep 0 aligned
    if ax1_neg_to_pos_ratio > ax2_neg_to_pos_ratio:
        # Adjust ax2 to match ax1's ratio
        new_ax2_min = -ax2_max * ax1_neg_to_pos_ratio
        ax2.set_ylim(new_ax2_min, ax2_max)
        ax1.set_ylim(ax1_min )
    else:
        # Adjust ax1 to match ax2's ratio
        new_ax1_min = -ax1_max * ax2_neg_to_pos_ratio
        ax1.set_ylim(new_ax1_min, ax1_max)

    # Add padding (white space) to both axes
    ax1_min, ax1_max = ax1.get_ylim()
    ax2_min, ax2_max = ax2.get_ylim()

    # Extend the limits by a percentage (padding_factor)
    ax1_padding = (ax1_max - ax1_min) * padding_factor
    ax2_padding = (ax2_max - ax2_min) * padding_factor

    # Set the new padded limits
    ax1.set_ylim(ax1_min - ax1_padding, ax1_max + ax1_padding)
    ax2.set_ylim(ax2_min - ax2_padding, ax2_max + ax2_padding)

# %% ../../nbs/04.02_PhasePlot.ipynb #01deba3f
def _data_to_plot(mae,  # CRLD multi-agent environment object
                  res:Iterable,  # range & resolution of flow arrows 
                  xinds:tuple,  # of indices of the phase space object to plot along the x axis
                  traj_len:int,  # trajectory len
                  NrRandom:int,  # how many random (in the other dimensions) stratgies for averaging 
                  # difffunc:Callable,  # to compute which kind of arrows to plot (RPE or dX)
                  phasespace_items:Callable,  # to obtain phase space items for one ax plot point
                  verbose=False  # shall I talk to you while working?
                  ):
        
    l = len(res)
    RPEs = np.zeros((mae.Z, l))
    dXs = np.zeros((mae.Z, l))

    for i in range(mae.Z):
        for j, xval in enumerate(res):
            Xs = _strategies(mae, xinds, xval, NrRandom)  # generate random strategies to average over
            RPE_ = np.zeros((NrRandom))
            for k, xk in enumerate(Xs):
                prederror = mae.TDerror(xk, norm=True) # compute pred error
                RPE_[k] = prederror[xinds[0], i, xinds[2]]  # pred error for indices of interest
            RPEs[i, j] = np.mean(RPE_)  # add trajectory
            dX_ = np.array(_dXisa_s(Xs, mae))  # compute change in Xisa
            dX = np.mean(dX_, axis=0)  # average over random strategies
            dXs[i, j] = dX[xinds[0], i, xinds[2]]  # dX for indices of interest
            
    return RPEs, dXs

# %% ../../nbs/04.02_PhasePlot.ipynb #e3d62880
def _dXisa_s(Xisa_s:Iterable, # of joint strategies `Xisa`
            mae  # CRLD multi-agent environment object
            ) -> np.ndarray:  # joint strategy differences 
    """Compute `Xisa`(t+1)-`Xisa`(t) for all `Xisa_s`."""
    return np.array([mae.step(Xisa)[0] - Xisa for Xisa in Xisa_s])

# %% ../../nbs/04.02_PhasePlot.ipynb #5872835a
def _strategies(mae,  # CRLD multi-agent environment object
                xinds:tuple,  # of indices of the phase space item to plot along the x axis
                xval:float,  # the value of the phase space item to plot along the x axis
                NrRandom,  # how many random (in the other dimensions) stratgies for averaging
               ) -> np.ndarray: # Array of joint strategies
    """
    Creates strategies (as a particular type of phase space item) for one ax plot point.
    All strategies have value `xval` at the `xinds` index and value `yval` at the `yinds`. 
    """   
    N, C, M = mae.N, mae.Q, mae.M  # Number of agents, conditions, actions
    # Xs = np.random.rand(NrRandom, N, C, M)  # random policies
    Xs = lhs(N*C*M, NrRandom).reshape(NrRandom, N, C, M)  # using latin hypercube sampling
    Xs = Xs / Xs.sum(axis=-1, keepdims=True)  # properly normalised
    
    xi, xc, xa = xinds; xa_ = tuple(set(range(M)) - set([xa]))
    
    Xs[:, xi, xc, xa] = xval  # setting x and y values
    
    # normalisation
    Xs[:,xi,xc,xa_] = (1-Xs[0, xi, xc, xa]) * Xs[:,xi,xc,xa_]\
        / np.sum(Xs[:,xi,xc,xa_], axis=-1, keepdims=True)
    
    return Xs
